import{_ as a,C as n,o as i,c as h,ak as c,E as o,j as t,a as r}from"./chunks/framework.DxrHb2fb.js";const m=JSON.parse('{"title":"HoverCard 悬浮卡片","description":"","frontmatter":{},"headers":[],"relativePath":"components/hover-card.md","filePath":"components/hover-card.md","lastUpdated":1790413976000}'),l={name:"components/hover-card.md"};function s(p,d,b,u,x,g){const e=n("XhDemo");return i(),h("div",null,[d[0]||(d[0]=c('<h1 id="hovercard-悬浮卡片" tabindex="-1">HoverCard 悬浮卡片 <a class="header-anchor" href="#hovercard-悬浮卡片" aria-label="Permalink to &quot;HoverCard 悬浮卡片&quot;">​</a></h1><p>指针停留后出现的信息卡：预览一个对象，不打断当前操作。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/hover-card" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/hover-card.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/hover-card" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/hover-card" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/hover-card.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>与 Tooltip 的分界在于卡片本体可交互：指针停在卡片上不收起，其中的链接与按钮都可点击</p>',5)),o(e,{src:"hover-card/01-basic"}),d[1]||(d[1]=c('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;hover-card&quot;</code>：<code>root</code> · <strong><code>trigger</code></strong> · <code>positioner</code> · <strong><code>content</code></strong> · <code>title</code> · <code>description</code> · <code>arrow</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="延时" tabindex="-1">延时 <a class="header-anchor" href="#延时" aria-label="Permalink to &quot;延时&quot;">​</a></h3><p>openDelay 默认 700ms，closeDelay 默认 300ms：收起等待正是留给指针从触发器移动到卡片上的通行时间</p>',6)),o(e,{src:"hover-card/02-delay"}),d[2]||(d[2]=t("h3",{id:"受控",tabindex:"-1"},[r("受控 "),t("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),d[3]||(d[3]=t("p",null,"传入 open 后由宿主决定；悬停与 Escape 都只发意图，最终是否写回由外部按钮共用的同一份状态决定",-1)),o(e,{src:"hover-card/03-controlled"}),d[4]||(d[4]=t("h3",{id:"尺寸",tabindex:"-1"},[r("尺寸 "),t("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[5]||(d[5]=t("p",null,"三档改变卡片的内边距与字号，不写 size 即默认档；把指针停在触发器上查看差别",-1)),o(e,{src:"hover-card/04-size"}),d[6]||(d[6]=t("h3",{id:"朝向与间距",tabindex:"-1"},[r("朝向与间距 "),t("a",{class:"header-anchor",href:"#朝向与间距","aria-label":'Permalink to "朝向与间距"'},"​")],-1)),d[7]||(d[7]=t("p",null,"placement 是请求值，空间不足时定位引擎会自动翻面；offset 调整卡片与触发器的距离",-1)),o(e,{src:"hover-card/05-placement"}),d[8]||(d[8]=t("h3",{id:"禁用",tabindex:"-1"},[r("禁用 "),t("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),d[9]||(d[9]=t("p",null,"disabled 只关闭卡片本身，触发器照常可点击、可聚焦，也照常不进入展开等待",-1)),o(e,{src:"hover-card/06-disabled"}),d[10]||(d[10]=c('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>链接或头像的预览：用户资料、文档摘要、商品简介。</li><li>信息属于顺带查看的内容，不需要专门点击。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>内容需要交互（按钮、表单）时，使用<a href="./popover">气泡卡片</a>。</li><li>只有一句文字时，使用<a href="./tooltip">文字提示</a>。</li><li>触摸端是主要场景。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li><code>openDelay</code> 与 <code>closeDelay</code> 成对：进入需要停留、离开有宽限，指针斜向移到卡片上不会误收。</li><li>开合状态可受控。</li><li>内容与 Popover 共用 M2 磨砂面：单层背景模糊、柔和顶光和浮层阴影，正文保持不透明。箭头只复用底色与边界，不叠加模糊；减少透明、高对比与强制色偏好由材质令牌统一响应。<code>--xh-hover-card-backdrop</code> 可覆盖模糊配方；打印时整块预览收起。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>触发器通常是<a href="./avatar">头像</a>或链接；卡片内使用<a href="./card">卡片</a>式的排版。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>打开延时设为几百毫秒，否则指针扫过一段文字会弹出一串卡片。</li><li>卡片内的信息在其他位置也应有正式入口。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>卡片内放操作按钮：指针移动过去的途中可能已经关闭。</li><li>延时为 0。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-hover-card&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhHoverCardArrow</code> <code>XhHoverCardContent</code> <code>XhHoverCardDescription</code> <code>XhHoverCardPositioner</code> <code>XhHoverCardRoot</code> <code>XhHoverCardTitle</code> <code>XhHoverCardTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useHoverCard</code></td></tr><tr><td>状态机</td><td><code>hoverCardMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/hover-card.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>placement</code></td><td><code>Placement</code></td><td></td><td>请求的浮层朝向，默认 bottom；空间不足时由定位引擎避让。</td></tr><tr><td><code>offset</code></td><td><code>number</code></td><td></td><td>浮层与锚点的间距（px）。</td></tr><tr><td><code>openDelay</code></td><td><code>number</code></td><td></td><td>悬停进入到展开的等待毫秒，默认 700。</td></tr><tr><td><code>closeDelay</code></td><td><code>number</code></td><td></td><td>指针离开 trigger 或 content 到收起的等待毫秒，默认 300。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，仅在显式提供时写到根节点上。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>只关闭卡片本身，不影响 trigger 元素自身的可用性。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，决定卡片的内边距档位。</td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: HoverCardOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图回调。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>HoverCardOpenChangeDetails</code></td><td>open 状态变化；detail 为 <code>{ open: boolean }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhHoverCardRoot</code></td><td><code>default</code></td><td><code>HoverCardRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhHoverCardPositioner</code></td><td><code>container</code></td><td><code>() =&gt; Element | null</code></td><td></td><td>浮层挂载的容器；未提供时按全局配置，再未提供时挂载到 body。</td></tr><tr><td><code>XhHoverCardRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;HoverCardRootSlotProps&gt;</code></td><td></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>closed</code> · <code>opening</code> · <code>visible</code> · <code>visible.open</code> · <code>visible.closing</code></p><p><strong>事件</strong>：<code>POINTER.ENTER</code> · <code>POINTER.LEAVE</code> · <code>FOCUS</code> · <code>BLUR</code> · <code>ESCAPE</code> · <code>OPEN</code> · <code>CLOSE</code> · <code>after.openDelay</code> · <code>after.closeDelay</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSE</code></p><p><strong>判据</strong>：<code>isOpenControlled</code> · <code>isDisabled</code> · <code>isFocusHeld</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getPositionerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDescriptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getArrowProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>not disabled</td><td>焦点进入 trigger 立即展开、离开卡片即收起，都不走延时</td></tr><tr><td><code>Escape</code></td><td>浮层可见（含收起等待期）</td><td>立即收起，不等 closeDelay</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-haspopup</code></td><td>&#39;dialog&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-describedby</code></td><td><code>description</code> 部件的 id | undefined</td></tr><tr><td><code>content</code></td><td><code>aria-hidden</code></td><td>!open || undefined</td></tr><tr><td><code>content</code></td><td><code>aria-labelledby</code></td><td><code>title</code> 部件的 id | <code>trigger</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>aria-modal</code></td><td>&#39;false&#39;</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;dialog&#39;</td></tr><tr><td><code>arrow</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/hover-card.css</code> 使用 <code>[data-scope=&quot;hover-card&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-hidden</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>positioner</code></td><td><code>data-positioned</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>content</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-xh-material</code></td><td>&#39;frosted&#39;</td></tr><tr><td><code>arrow</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-hover-card-arrow-size</code></td><td><code>arrow</code></td><td><code>--xh-_overlay-arrow-size</code></td><td><code>default</code></td><td><code>--xh-overlay-arrow-size</code></td><td>hover-card 的 arrow 部件 --xh-_overlay-arrow-size 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-backdrop</code></td><td><code>content</code></td><td><code>-webkit-backdrop-filter</code><br><code>backdrop-filter</code></td><td><code>xh-material=frosted</code></td><td><code>--xh-_material-backdrop</code></td><td>hover-card 的 content 部件 -webkit-backdrop-filter、backdrop-filter 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-bg</code></td><td><code>arrow</code><br><code>content</code></td><td><code>background</code></td><td><code>default</code><br><code>not([data-xh-action-control])</code><br><code>xh-material=frosted</code></td><td><code>--xh-_material-bg</code><br><code>--xh-material-frosted-bg</code></td><td>hover-card 的 arrow、content 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-border</code></td><td><code>arrow</code><br><code>content</code></td><td><code>border</code></td><td><code>default</code><br><code>not([data-xh-action-control])</code><br><code>xh-material=frosted</code></td><td><code>--xh-_material-border</code><br><code>--xh-material-frosted-border</code></td><td>hover-card 的 arrow、content 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-description-fg</code></td><td><code>description</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>hover-card 的 description 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-description-font-size</code></td><td><code>description</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-secondary-size</code></td><td>hover-card 的 description 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-fg</code></td><td><code>content</code></td><td><code>color</code></td><td><code>not([data-xh-action-control])</code><br><code>xh-material=frosted</code></td><td><code>--xh-_material-fg</code></td><td>hover-card 的 content 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-gap</code></td><td><code>content</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>hover-card 的 content 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-layer</code></td><td><code>positioner</code></td><td><code>z-index</code></td><td><code>default</code></td><td><code>--xh-_layer</code></td><td>hover-card 的 positioner 部件 z-index 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-max-h</code></td><td><code>content</code></td><td><code>max-block-size</code></td><td><code>default</code></td><td><code>--xh-overlay-max-h</code></td><td>hover-card 的 content 部件 max-block-size 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-max-w</code></td><td><code>content</code></td><td><code>max-inline-size</code></td><td><code>default</code></td><td><code>--xh-_hover-card-max-w</code></td><td>hover-card 的 content 部件 max-inline-size 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-px</code></td><td><code>content</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-_hover-card-pad</code></td><td>hover-card 的 content 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-py</code></td><td><code>content</code></td><td><code>padding-block</code></td><td><code>default</code></td><td><code>--xh-_hover-card-pad</code></td><td>hover-card 的 content 部件 padding-block 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-radius</code></td><td><code>content</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-overlay</code></td><td>hover-card 的 content 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-shadow</code></td><td><code>content</code></td><td><code>box-shadow</code></td><td><code>not([data-xh-action-control])</code><br><code>xh-material=frosted</code></td><td><code>--xh-_material-shadow</code></td><td>hover-card 的 content 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-title-fg</code></td><td><code>title</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>hover-card 的 title 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-title-font-size</code></td><td><code>title</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-label-size</code></td><td>hover-card 的 title 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-title-font-weight</code></td><td><code>title</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-font-weight-semibold</code></td><td>hover-card 的 title 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-hover-card-trigger-gap</code></td><td><code>trigger</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-control-gap-sm</code></td><td>hover-card 的 trigger 部件 gap 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>动效角色：出现（锚定面板）（见<a href="./../design/motion#角色">动效规范</a>）。</p><p>共享关键帧 <code>xh-overlay-pop-in</code> · <code>xh-pop-out</code> 由 <code>family/motion.css</code> 提供，皮肤 <code>@import</code> 它，单独引入仍成立。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>皮肤之外还有一段：退场由适配器的退场闸门把关，动画播完才真收起。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',61))])}const v=a(l,[["render",s]]);export{m as __pageData,v as default};
